-- Deploy inertly. The operator must separately authorize optional email sends.
update private.reminder_delivery_control set delivery_enabled=false;

create table private.reminder_channel_history (
 user_id uuid not null references auth.users(id) on delete cascade,
 channel_id text not null check(channel_id ~ '^UC[A-Za-z0-9_-]{22}$'),
 ever_added boolean not null default false,
 currently_owned boolean not null default false,
 deleted_at timestamptz,
 primary key(user_id,channel_id)
);
alter table private.reminder_channel_history enable row level security;
revoke all on private.reminder_channel_history from public,anon,authenticated,service_role;
create index reminder_channel_history_owned on private.reminder_channel_history(user_id,channel_id) where currently_owned;
create table private.email_channel_history_sources (
 user_id uuid primary key references auth.users(id) on delete cascade,
 fingerprint text not null
);
alter table private.email_channel_history_sources enable row level security;
revoke all on private.email_channel_history_sources from public,anon,authenticated,service_role;
create index reminder_channel_history_popularity on private.reminder_channel_history(channel_id,user_id) where ever_added;

alter table private.reminder_discovery_channels
 add column is_onboarding boolean not null default true,
 add column thumbnail_url text not null default '';
alter table private.reminder_discovery_channels drop constraint reminder_discovery_channels_catalog_id_check,
 add constraint reminder_discovery_channels_catalog_id_check check(length(catalog_id) between 1 and 100 and catalog_id ~ '^[A-Za-z0-9_-]+$');
alter table public.reminder_channel_follows add column streak_video_mode text check(streak_video_mode in ('new','continue'));
alter table public.reminder_eligibility_snapshots
 add column learning_languages text[] not null default '{}';
alter table private.reminder_deliveries
 add column discovery_channels jsonb not null default '[]'::jsonb
  check(jsonb_typeof(discovery_channels)='array' and jsonb_array_length(discovery_channels)<=6),
 add column streak_days integer check(streak_days between 0 and 10000),
 add column remaining_minutes integer check(remaining_minutes between 1 and 10),
 add column video_mode text check(video_mode in ('new','continue'));

-- A permanent owner/channel tombstone survives re-add, undo and later profile
-- generations. It is private; only aggregate ranking ever uses peer history.
create function private.remember_email_channels(p_user uuid,p_old jsonb,p_new jsonb,p_at timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare v_fingerprint text;
begin
 if p_old is not null and p_old->'channels' is not distinct from p_new->'channels'
  and p_old->'removedChannelIds' is not distinct from p_new->'removedChannelIds' then return; end if;
 v_fingerprint:=private.reminder_input_digest(jsonb_build_object('channels',coalesce(p_new->'channels','[]'::jsonb),'removedChannelIds',coalesce(p_new->'removedChannelIds','[]'::jsonb)));
 if exists(select 1 from private.email_channel_history_sources c where c.user_id=p_user and c.fingerprint=v_fingerprint) then return; end if;
 on conflict(user_id) do update set fingerprint=excluded.fingerprint;
 update private.reminder_channel_history h set currently_owned=false,deleted_at=coalesce(h.deleted_at,p_at)
  where h.user_id=p_user and h.currently_owned and not exists(select 1 from jsonb_array_elements(coalesce(p_new->'channels','[]'::jsonb)) c where c.value->>'id'=h.channel_id);
 select p_user,c.value->>'id',true,true
 from jsonb_array_elements(coalesce(p_new->'channels','[]'::jsonb)) c
 where c.value->>'id' ~ '^UC[A-Za-z0-9_-]{22}$'
 on conflict(user_id,channel_id) do update set ever_added=true,currently_owned=true where not h.ever_added or not h.currently_owned;
 select p_user,removed.id,p_at from (
  select r.value as id from jsonb_array_elements_text(coalesce(p_new->'removedChannelIds','[]'::jsonb)) r
  union
  select c.value->>'id' from jsonb_array_elements(coalesce(p_old->'channels','[]'::jsonb)) c
   where not exists(select 1 from jsonb_array_elements(coalesce(p_new->'channels','[]'::jsonb)) n where n.value->>'id'=c.value->>'id')
 ) removed where removed.id ~ '^UC[A-Za-z0-9_-]{22}$'
 on conflict(user_id,channel_id) do update set deleted_at=excluded.deleted_at where h.deleted_at is null;
end $$;

create function private.email_channel_record_history()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if coalesce(new.kind,old.kind)<>'section' or coalesce(new.record_key,old.record_key)<>'config' then return null; end if;
 if tg_op='UPDATE' and old.value->'channels' is not distinct from new.value->'channels'
  and old.value->'removedChannelIds' is not distinct from new.value->'removedChannelIds' then return null; end if;
 if coalesce(new.kind,old.kind)='section' and coalesce(new.record_key,old.record_key)='config' then
  perform private.remember_email_channels(coalesce(new.user_id,old.user_id),
   case when tg_op<>'INSERT' then old.value end,case when tg_op<>'DELETE' then new.value end,statement_timestamp());
 end if;
 return null;
end $$;
create trigger email_channel_record_history after insert or update or delete on private.learner_profile_current_records
 for each row execute function private.email_channel_record_history();

create function private.email_discovery_recommendations(p_user uuid,p_at timestamptz,p_exclude_delivery uuid default null)
returns jsonb language sql stable security definer set search_path='' as $$
 with ranked as (
  select r.* from private.reminder_discovery_channels r
  join public.reminder_eligibility_snapshots s on s.user_id=p_user
  where r.learning_language=any(s.learning_languages)
   and not exists(select 1 from public.reminder_channel_follows f where f.user_id=p_user and f.channel_id=r.channel_id)
   and not exists(select 1 from private.reminder_channel_history h where h.user_id=p_user and h.channel_id=r.channel_id and (h.deleted_at is not null or h.currently_owned))
   and not exists(select 1 from private.reminder_deliveries d where d.user_id=p_user and d.id is distinct from p_exclude_delivery
    and d.email_type='discovery' and d.may_have_sent and d.send_started_at>p_at-interval '90 days'
    and (d.channel_id=r.channel_id or exists(select 1 from jsonb_array_elements(d.discovery_channels) c where c.value->>'channelId'=r.channel_id)))
  order by r.is_onboarding,
   (select count(*) from private.reminder_channel_history h where h.channel_id=r.channel_id and h.ever_added and h.user_id<>p_user) desc,r.channel_id
  limit 6
 ) select coalesce(jsonb_agg(jsonb_build_object('channelId',r.channel_id,'name',r.channel_name,
  'thumbnailUrl',r.thumbnail_url,'learningLanguage',r.learning_language,'summary',r.summary)), '[]'::jsonb) from ranked r;
$$;

-- Recheck every frozen card, not just the representative channel. A changed
-- exclusion or catalog invalidates the occurrence; it never rebuilds a retry.
create function private.email_discovery_payload_current(p_delivery uuid,p_at timestamptz)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from private.reminder_deliveries d join public.reminder_eligibility_snapshots s on s.user_id=d.user_id
  where d.id=p_delivery and jsonb_array_length(d.discovery_channels) between 1 and 6
  and not exists(select 1 from jsonb_array_elements(d.discovery_channels) c where
   not exists(select 1 from private.reminder_discovery_channels r where r.channel_id=c.value->>'channelId'
    and r.learning_language=any(s.learning_languages) and r.channel_name=c.value->>'name' and r.thumbnail_url=c.value->>'thumbnailUrl')
   or exists(select 1 from public.reminder_channel_follows f where f.user_id=d.user_id and f.channel_id=c.value->>'channelId')
   or exists(select 1 from private.reminder_channel_history h where h.user_id=d.user_id and h.channel_id=c.value->>'channelId' and (h.deleted_at is not null or h.currently_owned))
   or exists(select 1 from private.reminder_deliveries previous where previous.user_id=d.user_id and previous.id<>d.id
    and previous.email_type='discovery' and previous.may_have_sent and previous.send_started_at>p_at-interval '90 days'
    and (previous.channel_id=c.value->>'channelId' or exists(select 1 from jsonb_array_elements(previous.discovery_channels) pc where pc.value->>'channelId'=c.value->>'channelId')))));
$$;

create function private.freeze_email_design_payload()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and new.email_type is not distinct from old.email_type then return new; end if;
 -- Historical/provider-started records retain their original content.
 if tg_op='INSERT' and new.may_have_sent then return new; end if;
 if new.email_type='discovery' then
  new.discovery_channels:=private.email_discovery_recommendations(new.user_id,new.scheduled_for,new.id);
  new.channel_id:=new.discovery_channels#>>'{0,channelId}';
  new.channel_name:=new.discovery_channels#>>'{0,name}';
  new.channel_summary:=new.discovery_channels#>>'{0,summary}';
  new.streak_days:=null;new.remaining_minutes:=null;new.video_mode:=null;
 elsif new.email_type='streak' then
  new.discovery_channels:='[]'::jsonb;
  select s.current_streak_days,greatest(1,least(10,ceil(private.reminder_study_threshold()-coalesce(private.reminder_study_points(new.user_id,new.scheduled_local_date),0))::integer))
   into new.streak_days,new.remaining_minutes from public.reminder_eligibility_snapshots s where s.user_id=new.user_id;
  new.video_mode:='new';
  select f.channel_id,f.channel_name,f.streak_video_id,f.streak_video_title,f.streak_video_published_at,coalesce(f.streak_video_mode,'new')
   into new.channel_id,new.channel_name,new.video_id,new.video_title,new.video_published_at,new.video_mode
   from public.reminder_channel_follows f where f.user_id=new.user_id and f.streak_video_id is not null
   order by (f.streak_video_mode='continue') desc,f.streak_video_published_at desc,f.channel_id limit 1;
 end if;
 return new;
end $$;
create trigger freeze_email_design_payload before insert or update of email_type on private.reminder_deliveries
 for each row execute function private.freeze_email_design_payload();

-- Populate old accepted heads in bounded batches even when peers did not opt
-- into email. Never count a browser assertion or expose a learner list.
create table private.email_channel_backfill (
 user_id uuid primary key references auth.users(id) on delete cascade
);
alter table private.email_channel_backfill enable row level security;
revoke all on private.email_channel_backfill from public,anon,authenticated,service_role;
create function private.refresh_email_channel_history(p_limit integer,p_at timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare owner record; head public.learner_profile_heads%rowtype; config jsonb;
begin
 for owner in select u.id from auth.users u join private.email_channel_backfill b on b.user_id=u.id
  order by u.id limit p_limit for update of u skip locked
 loop
  select h.* into head from public.learner_profile_heads h where h.user_id=owner.id;
  if head.records_active then
   select r.value into config from private.learner_profile_current_records r where r.user_id=owner.id
    and r.profile_id=head.profile_id and r.generation=head.generation and r.kind='section' and r.record_key='config';
  else
   select v.envelope#>'{profile,config}' into config from public.learner_profile_versions v where v.id=head.current_version_id and v.user_id=owner.id;
  end if;
  if config is not null then perform private.remember_email_channels(owner.id,null,config,p_at); end if;
  delete from private.email_channel_backfill where user_id=owner.id;
 end loop;
end $$;
revoke execute on function private.refresh_email_channel_history(integer,timestamptz) from public,anon,authenticated,service_role;

-- Snapshot of the reviewed application catalogs.
on conflict(channel_id) do update set catalog_id=excluded.catalog_id,learning_language=excluded.learning_language,channel_name=excluded.channel_name,summary=excluded.summary,is_onboarding=excluded.is_onboarding,thumbnail_url=excluded.thumbnail_url;

create or replace function private.reminder_config_input(p_value jsonb)
returns jsonb language sql immutable security invoker set search_path = '' as $$
  select pg_catalog.jsonb_build_object('channels',coalesce(p_value->'channels','[]'::jsonb),
    'removedChannelIds',coalesce(p_value->'removedChannelIds','[]'::jsonb),'includeShorts',p_value->'includeShorts','locale',p_value->'locale');
$$;

create or replace function private.reminder_accepted_head_changed()
returns trigger language plpgsql security definer set search_path = '' as $$
declare source private.reminder_projection_sources%rowtype; inputs jsonb; fingerprint text; previous_fingerprint text;
begin
  if tg_op='UPDATE' and new.profile_id=old.profile_id and new.generation=old.generation and new.revision=old.revision then return new; end if;
  if not new.records_active then
    select private.reminder_profile_inputs(v.envelope->'profile') into inputs from public.learner_profile_versions v
      where v.id=new.current_version_id and v.user_id=new.user_id and v.profile_id=new.profile_id
        and v.generation=new.generation and v.revision=new.revision;
    if inputs is not null then perform private.remember_email_channels(new.user_id,null,inputs->'config',statement_timestamp()); end if;
    fingerprint:=case when inputs is not null then private.reminder_input_digest(inputs) end;
    select s.* into source from private.reminder_projection_sources s where s.user_id=new.user_id;
    if tg_op='UPDATE' and source.input_fingerprint is null then
      -- Before the first bounded projection, there is no cached fingerprint.
      -- A cosmetic legacy write must not turn an old accepted profile into
      -- recent study/settings activity merely by warming this new cache.
      select private.reminder_input_digest(private.reminder_profile_inputs(v.envelope->'profile')) into previous_fingerprint
        from public.learner_profile_versions v where v.id=old.current_version_id and v.user_id=old.user_id
          and v.profile_id=old.profile_id and v.generation=old.generation and v.revision=old.revision;
    end if;
      values(new.user_id,fingerprint,case when tg_op='INSERT' or (coalesce(source.input_fingerprint,previous_fingerprint) is not null
        and coalesce(source.input_fingerprint,previous_fingerprint) is distinct from fingerprint)
        then pg_catalog.statement_timestamp() else source.relevant_activity_at end) on conflict(user_id) do update
      set input_version=case when coalesce(s.input_fingerprint,previous_fingerprint) is not distinct from excluded.input_fingerprint then s.input_version else s.input_version+1 end,
        dirty=s.dirty or coalesce(s.input_fingerprint,previous_fingerprint) is distinct from excluded.input_fingerprint,
        relevant_activity_at=excluded.relevant_activity_at,
        retry_after=case when coalesce(s.input_fingerprint,previous_fingerprint) is distinct from excluded.input_fingerprint then null else s.retry_after end,
        failure_reason=case when coalesce(s.input_fingerprint,previous_fingerprint) is distinct from excluded.input_fingerprint then null else s.failure_reason end,
        input_fingerprint=excluded.input_fingerprint;
  else
  end if;
  select s.* into strict source from private.reminder_projection_sources s where s.user_id=new.user_id;
  if tg_op='UPDATE' and new.profile_id=old.profile_id and new.generation=old.generation and not source.dirty then
    update public.reminder_eligibility_snapshots s set accepted_revision=new.revision
      where s.user_id=new.user_id and s.accepted_profile_id=old.profile_id and s.accepted_generation=old.generation
        and s.accepted_revision=old.revision and s.input_version=source.input_version and s.rule_version=1;
  elsif tg_op='UPDATE' and (new.profile_id is distinct from old.profile_id or new.generation is distinct from old.generation) then
    update private.reminder_projection_sources set dirty=true,input_version=input_version+1,retry_after=null,failure_reason=null where user_id=new.user_id;
  end if;
  return new;
end;
$$;

create or replace function private.reminder_video_input(p_value jsonb)
returns jsonb language sql immutable security invoker set search_path = '' as $$
  select pg_catalog.jsonb_build_object('id',p_value->'id','channelId',p_value->'channelId',
    'title',p_value->'title','publishedAt',p_value->'publishedAt','duration',p_value->'duration',
    'resumeAtSeconds',p_value->'resumeAtSeconds','pausedAt',p_value->'pausedAt','isShort',p_value->'isShort','status',p_value->'status','hiddenFromGrid',p_value->'hiddenFromGrid',
    'removedFromFeedAt',p_value->'removedFromFeedAt','watchProgress',coalesce(p_value->'watchProgress','[]'::jsonb));
$$;

create or replace function private.refresh_reminder_eligibility(p_user uuid,p_now timestamptz)
returns boolean language plpgsql volatile security definer set search_path = '' as $$
declare head public.learner_profile_heads%rowtype; source private.reminder_projection_sources%rowtype;
  inputs jsonb; config jsonb; learner jsonb; videos jsonb; anki jsonb; fingerprint text;
  zone text; lang text; locale_name text; local_day date; last_day date; streak integer:=0; cursor_day date; observed timestamptz;
begin
  select h.* into head from public.learner_profile_heads h where h.user_id=p_user for update;
  if not found then return false; end if;
  select p.timezone into zone from public.reminder_preferences p where p.user_id=p_user;
  if zone is null or not exists(select 1 from pg_catalog.pg_timezone_names where name=zone) then return false; end if;
  local_day:=(p_now at time zone zone)::date;
  select s.* into strict source from private.reminder_projection_sources s where s.user_id=p_user for update;
  if private.reminder_projection_matches_head(p_user) then
    select max(d.study_date) into last_day from private.reminder_projection_days d where d.user_id=p_user
      and d.study_date<=local_day and d.points>=private.reminder_study_threshold();
    cursor_day:=case when private.reminder_study_points(p_user,local_day)>=private.reminder_study_threshold() then local_day else local_day-1 end;
    while coalesce(private.reminder_study_points(p_user,cursor_day),0)>=private.reminder_study_threshold() and streak<10000 loop
      streak:=streak+1;cursor_day:=cursor_day-1;
    end loop;
    update public.reminder_eligibility_snapshots set timezone=zone,study_date=local_day,
      points_today=least(100000,floor(private.reminder_study_points(p_user,local_day)))::integer,
      last_qualified_study_date=last_day,current_streak_days=streak where user_id=p_user;
    update private.reminder_projection_sources set refreshed_at=p_now where user_id=p_user;
    return true;
  end if;
  if head.records_active then
    select pg_catalog.jsonb_object_agg(r.record_key,r.value) into config from private.learner_profile_current_records r
      where r.user_id=p_user and r.profile_id=head.profile_id and r.generation=head.generation
        and r.kind='section' and r.record_key in ('config','learnerProfile');
    select coalesce(pg_catalog.jsonb_object_agg(r.record_key,private.reminder_video_input(r.value)),'{}'::jsonb) into videos
      from private.learner_profile_current_records r where r.user_id=p_user and r.profile_id=head.profile_id
        and r.generation=head.generation and r.kind='video';
    select coalesce(pg_catalog.jsonb_object_agg(r.record_key,r.value),'{}'::jsonb) into anki
      from private.learner_profile_current_records r where r.user_id=p_user and r.profile_id=head.profile_id
        and r.generation=head.generation and r.kind='anki';
    inputs:=private.reminder_profile_inputs(config||pg_catalog.jsonb_build_object('videos',videos,'anki',anki));
  else
    select private.reminder_profile_inputs(v.envelope->'profile') into inputs from public.learner_profile_versions v
      where v.id=head.current_version_id and v.user_id=p_user and v.profile_id=head.profile_id
        and v.generation=head.generation and v.revision=head.revision;
  end if;
  if inputs is null then return false; end if;
  fingerprint:=private.reminder_input_digest(inputs); config:=inputs->'config'; learner:=inputs->'learnerProfile';
  videos:=inputs->'videos';anki:=inputs->'anki';
  locale_name:=case when config->>'locale' in ('en','zh-Hant','zh-Hans','es','fr') then config->>'locale' else 'en' end;
  lang:=learner#>>'{languages,0}';
  if lang not in ('mandarin','japanese','korean','spanish','french','german','english','other') then lang:=null; end if;
  delete from private.reminder_projection_days where user_id=p_user;
    select p_user,f.study_date,sum(f.points) from (
      select (e.value->>'studyDay')::date as study_date,coalesce((e.value->>'experienceSeconds')::numeric,0)/60 as points
        from pg_catalog.jsonb_each(videos) v cross join lateral pg_catalog.jsonb_array_elements(coalesce(v.value->'watchProgress','[]'::jsonb)) e
        where coalesce((e.value->>'experienceSeconds')::numeric,0)>0
      union all select a.key::date,coalesce((a.value->>'experienceReviews')::numeric,0) from pg_catalog.jsonb_each(anki) a
    ) f group by f.study_date;
  select greatest(source.relevant_activity_at,
    case when (learner->>'updatedAt')::timestamptz<=p_now then (learner->>'updatedAt')::timestamptz end,
    max(f.observed_at) filter(where f.observed_at<=p_now)) into observed from (
    select (e.value->>'watchedAt')::timestamptz as observed_at from pg_catalog.jsonb_each(videos) v
      cross join lateral pg_catalog.jsonb_array_elements(coalesce(v.value->'watchProgress','[]'::jsonb)) e
      where coalesce((e.value->>'experienceSeconds')::numeric,0)>0
    union all select (a.value->>'observedAt')::timestamptz from pg_catalog.jsonb_each(anki) a
      where coalesce((a.value->>'reviewed')::numeric,0)>0 or coalesce((a.value->>'created')::numeric,0)>0
    ) f;
  select max(d.study_date) into last_day from private.reminder_projection_days d where d.user_id=p_user
    and d.study_date<=local_day and d.points>=private.reminder_study_threshold();
  select case when coalesce(d.points,0)>=private.reminder_study_threshold() then local_day else local_day-1 end into cursor_day
    from (select 1) x left join private.reminder_projection_days d on d.user_id=p_user and d.study_date=local_day;
  while exists(select 1 from private.reminder_projection_days d where d.user_id=p_user and d.study_date=cursor_day and d.points>=private.reminder_study_threshold()) and streak<10000 loop
    streak:=streak+1;cursor_day:=cursor_day-1;
  end loop;
    last_qualified_study_date,current_streak_days,updated_at,accepted_profile_id,accepted_generation,accepted_revision,
    rule_version,input_version,input_fingerprint,relevant_activity_at,study_day_provenance)
    values(p_user,zone,locale_name,lang,local_day,least(100000,floor(coalesce((select d.points from private.reminder_projection_days d
      where d.user_id=p_user and d.study_date=local_day),0)))::integer,last_day,streak,p_now,
      head.profile_id,head.generation,head.revision,1,source.input_version,fingerprint,observed,'accepted-study-day-v1')
    on conflict(user_id) do update set timezone=excluded.timezone,locale=excluded.locale,learning_language=excluded.learning_language,
      study_date=excluded.study_date,points_today=excluded.points_today,last_qualified_study_date=excluded.last_qualified_study_date,
      current_streak_days=excluded.current_streak_days,updated_at=excluded.updated_at,accepted_profile_id=excluded.accepted_profile_id,
      accepted_generation=excluded.accepted_generation,accepted_revision=excluded.accepted_revision,rule_version=excluded.rule_version,
      input_version=excluded.input_version,input_fingerprint=excluded.input_fingerprint,relevant_activity_at=excluded.relevant_activity_at,
      study_day_provenance=excluded.study_day_provenance;
  update public.reminder_eligibility_snapshots set learning_languages=array(select value from jsonb_array_elements_text(coalesce(learner->'languages','[]'::jsonb)) l(value) where value in ('mandarin','japanese','korean','spanish','french','german','english')) where user_id=p_user;
  perform private.remember_email_channels(p_user,null,config,p_now);
  delete from public.reminder_channel_follows where user_id=p_user;
    latest_video_id,latest_video_title,latest_video_published_at,streak_video_id,streak_video_title,streak_video_published_at,streak_video_mode)
    select p_user,c.value->>'id',left(coalesce(nullif(c.value->>'name',''),c.value->>'id'),200),p_now,
      latest.value->>'id',left(latest.value->>'title',300),(latest.value->>'publishedAt')::timestamptz,
      unwatched.value->>'id',left(unwatched.value->>'title',300),(unwatched.value->>'publishedAt')::timestamptz,case when coalesce((unwatched.value->>'resumeAtSeconds')::numeric,0)>0 then 'continue' else 'new' end
    from pg_catalog.jsonb_array_elements(coalesce(config->'channels','[]'::jsonb)) with ordinality c(value,position)
    left join lateral(select v.value from pg_catalog.jsonb_each(videos) v where v.value->>'channelId'=c.value->>'id'
      and v.value->>'id' ~ '^[A-Za-z0-9_-]{11}$' and length(v.value->>'title')>0 and v.value->>'publishedAt' is not null
      and coalesce((v.value->>'hiddenFromGrid')::boolean,false)=false and v.value->>'removedFromFeedAt' is null
      and (coalesce((config->>'includeShorts')::boolean,true) or (coalesce((v.value->>'duration')::numeric,0)<=0 or (v.value->>'duration')::numeric>=180))
      order by v.value->>'publishedAt' desc,v.key limit 1) latest on true
    left join lateral(select v.value from pg_catalog.jsonb_each(videos) v where v.value->>'channelId'=c.value->>'id'
      and v.value->>'id' ~ '^[A-Za-z0-9_-]{11}$' and length(v.value->>'title')>0 and v.value->>'publishedAt' is not null
      and v.value->>'status'='unwatched' and coalesce((v.value->>'hiddenFromGrid')::boolean,false)=false and v.value->>'removedFromFeedAt' is null
      and (coalesce((config->>'includeShorts')::boolean,true) or (coalesce((v.value->>'duration')::numeric,0)<=0 or (v.value->>'duration')::numeric>=180))
      order by (coalesce((v.value->>'resumeAtSeconds')::numeric,0)>0) desc,v.value->>'pausedAt' desc nulls last,v.value->>'publishedAt' desc,v.key limit 1) unwatched on true
    where c.position<=250 and c.value->>'id' ~ '^UC[A-Za-z0-9_-]{22}$' on conflict(user_id,channel_id) do nothing;
  update private.reminder_projection_sources set dirty=false,input_fingerprint=fingerprint,refreshed_at=p_now,retry_after=null,failure_reason=null where user_id=p_user;
  return true;
end;
$$;

create or replace function public.refresh_reminder_eligibility_snapshots(p_limit integer default 10,p_now timestamptz default now())
returns integer language plpgsql volatile security definer set search_path = '' as $$
declare target record; refreshed integer:=0;
begin
  if p_limit is null or p_limit not between 1 and 100 or p_now is null then raise exception 'Invalid reminder projection bound' using errcode='22023'; end if;
  perform private.refresh_email_channel_history(p_limit,p_now);
  for target in select u.id from auth.users u join public.learner_profile_heads h on h.user_id=u.id
    join public.reminder_preferences p on p.user_id=u.id
    left join private.reminder_projection_sources s on s.user_id=u.id
    where u.deleted_at is null and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false)
      and (s.retry_after is null or s.retry_after<=p_now)
      and (s.user_id is null or s.dirty or s.refreshed_at is null or s.refreshed_at<p_now-interval '5 minutes')
    order by s.refreshed_at nulls first,u.id limit p_limit for update of u skip locked
  loop
    begin
      if private.refresh_reminder_eligibility(target.id,p_now) then refreshed:=refreshed+1; end if;
    exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow
      or numeric_value_out_of_range or not_null_violation or check_violation then
      -- A corrupt accepted owner must not prevent other owners' bounded work.
      -- Keep its head untouched, invalidate derived authority, and avoid a hot
      -- retry loop. This exposes an operator reason without profile contents.
        values(target.id,true,p_now,p_now+interval '1 hour','invalid-accepted-input') on conflict(user_id) do update
        set dirty=true,refreshed_at=p_now,retry_after=excluded.retry_after,failure_reason=excluded.failure_reason;
    end;
  end loop;
  return refreshed;
end;
$$;

create or replace function private.reminder_candidates(p_utc_date date,p_at timestamptz)
returns table(user_id uuid,local_date date,scheduled_for timestamptz,timezone text,
 locale text,learning_language text,consent_version text,consent_granted_at timestamptz,
 snapshot_updated_at timestamptz,enrollment_epoch bigint,choice_version bigint,
 email_type text,channel_id text,channel_name text,channel_summary text,
 video_id text,video_title text,video_published_at timestamptz)
language sql stable set search_path='' as $$
 with owners as materialized (
  select p.*,s.timezone as accepted_timezone,s.locale as accepted_locale,s.learning_language,
   s.updated_at as snapshot_updated_at,s.relevant_activity_at,
   (((p_utc_date+o.day_offset)+time '19:00') at time zone s.timezone) as due,
   (p_utc_date+o.day_offset)::date as local_date
  from public.reminder_preferences p join public.reminder_eligibility_snapshots s using(user_id)
  cross join (values(-1),(0),(1)) o(day_offset)
  cross join private.reminder_delivery_control ctl
  where s.timezone=p.timezone
   and private.reminder_projection_matches_head(p.user_id)
   and (ctl.admission_mode='public' or exists(select 1 from private.reminder_delivery_testers t
     where t.user_id=p.user_id))
 ), eligible as (
  select o.*,case when public.reminder_type_enrolled(o.user_id,'streak')
   and private.reminder_study_points(o.user_id,o.local_date-1)>=private.reminder_study_threshold()
   and coalesce(private.reminder_study_points(o.user_id,o.local_date),0)<private.reminder_study_threshold()
   then 'streak' when public.reminder_type_enrolled(o.user_id,'discovery')
   and o.learning_language is not null and o.relevant_activity_at>=p_at-interval '30 days'
   and not exists(select 1 from private.reminder_deliveries d where d.user_id=o.user_id
     and d.email_type='discovery' and d.may_have_sent
     and d.scheduled_local_date>o.local_date-7 and d.scheduled_local_date<=o.local_date)
   then 'discovery' end as kind
  from owners o where (o.due at time zone 'UTC')::date=p_utc_date
   and not exists(select 1 from private.reminder_deliveries d where d.user_id=o.user_id
     and d.may_have_sent and d.send_started_at>o.due-interval '24 hours'
     and d.send_started_at<=o.due)
 )
 select e.user_id,e.local_date,e.due,e.accepted_timezone,e.accepted_locale,e.learning_language,
  e.consent_version,e.consent_granted_at,e.snapshot_updated_at,e.enrollment_epoch,
  case e.kind when 'streak' then e.streak_choice_version else e.discovery_choice_version end,
  e.kind,c.channel_id,c.channel_name,c.summary,
  null::text,null::text,null::timestamptz
 from eligible e left join lateral (
  select r.* from private.reminder_discovery_channels r
  where e.kind='discovery' and r.channel_id=(private.email_discovery_recommendations(e.user_id,e.due)#>>'{0,channelId}')

 ) c on true
 where e.kind='streak' or (e.kind='discovery' and c.channel_id is not null)
$$;

create or replace function private.typed_reminder_delivery_is_current(p_delivery_id uuid,p_at timestamptz)
returns boolean language sql stable security invoker set search_path='' as $$
 select exists(select 1 from private.reminder_deliveries d
 join public.reminder_preferences p on p.user_id=d.user_id
 join public.reminder_eligibility_snapshots s on s.user_id=d.user_id
 join private.reminder_delivery_control ctl on ctl.singleton
 where d.id=p_delivery_id and d.email_type is not null and p_at is not null
 and p_at>=d.scheduled_for and p_at<d.scheduled_for+interval '1 hour'
 and (p_at at time zone d.timezone)::date=d.scheduled_local_date
 and (ctl.admission_mode='public' or exists(select 1 from private.reminder_delivery_testers t where t.user_id=d.user_id))
 and public.reminder_type_enrolled(d.user_id,d.email_type)
 and p.enrollment_epoch=d.enrollment_epoch
 and (case d.email_type when 'streak' then p.streak_choice_version else p.discovery_choice_version end)=d.choice_version
 and private.reminder_projection_matches_head(d.user_id)
 and s.timezone=d.timezone and s.locale=d.locale and p.timezone=d.timezone
 and not exists(select 1 from private.reminder_deliveries previous where previous.user_id=d.user_id
   and previous.id<>d.id and previous.may_have_sent and previous.send_started_at>p_at-interval '24 hours')
 and ((d.email_type='streak' and (d.streak_days is null or d.streak_days=s.current_streak_days) and (d.video_id is null or exists(select 1 from public.reminder_channel_follows vf where vf.user_id=d.user_id and vf.channel_id=d.channel_id and vf.streak_video_id=d.video_id and vf.streak_video_title=d.video_title and coalesce(vf.streak_video_mode,'new')=coalesce(d.video_mode,'new'))) and (d.remaining_minutes is null or d.remaining_minutes=greatest(1,ceil(private.reminder_study_threshold()-coalesce(private.reminder_study_points(d.user_id,d.scheduled_local_date),0))::integer)) and private.reminder_study_points(d.user_id,d.scheduled_local_date-1)>=private.reminder_study_threshold()
   and coalesce(private.reminder_study_points(d.user_id,d.scheduled_local_date),0)<private.reminder_study_threshold())
 or (d.email_type='discovery'
   and not(public.reminder_type_enrolled(d.user_id,'streak')
     and private.reminder_study_points(d.user_id,d.scheduled_local_date-1)>=private.reminder_study_threshold()
     and coalesce(private.reminder_study_points(d.user_id,d.scheduled_local_date),0)<private.reminder_study_threshold())
   and private.email_discovery_payload_current(d.id,p_at)
   and s.learning_language=d.learning_language
   and s.relevant_activity_at>=p_at-interval '30 days'
   and exists(select 1 from private.reminder_discovery_channels r where r.channel_id=d.channel_id
     and r.learning_language=any(s.learning_languages) and r.channel_name=d.channel_name and r.summary=d.channel_summary)
   and not exists(select 1 from public.reminder_channel_follows f where f.user_id=d.user_id and f.channel_id=d.channel_id)
   and not exists(select 1 from private.reminder_deliveries previous where previous.user_id=d.user_id
     and previous.id<>d.id and previous.email_type='discovery' and previous.may_have_sent
     and ((previous.scheduled_local_date>d.scheduled_local_date-7)
       or (previous.channel_id=d.channel_id and previous.send_started_at>p_at-interval '90 days'))))))
$$;

create function public.claim_due_typed_reminder_design(
 p_now timestamptz default now(),p_batch_size integer default 10,
 p_due_window_seconds integer default 3600,p_lease_seconds integer default 300)
returns table(delivery_id uuid,claim_token uuid,user_id uuid,scheduled_local_date date,
 scheduled_for timestamptz,timezone text,locale text,consent_version text,attempt_count integer,
 email_type text,learning_language text,channel_id text,channel_name text,channel_summary text,
 video_id text,video_title text,video_published_at timestamptz,
 discovery_channels jsonb,streak_days integer,remaining_minutes integer,video_mode text)
language plpgsql volatile security definer set search_path='' as $$
declare c record;
begin
 for c in select * from public.claim_due_typed_reminder_live(p_now,p_batch_size,p_due_window_seconds,p_lease_seconds)
 loop
  return query select c.delivery_id,c.claim_token,c.user_id,c.scheduled_local_date,c.scheduled_for,c.timezone,c.locale,
   c.consent_version,c.attempt_count,c.email_type,c.learning_language,c.channel_id,c.channel_name,c.channel_summary,
   c.video_id,c.video_title,c.video_published_at,d.discovery_channels,d.streak_days,d.remaining_minutes,d.video_mode
   from private.reminder_deliveries d where d.id=c.delivery_id;
 end loop;
end $$;
revoke execute on function public.claim_due_typed_reminder_design(timestamptz,integer,integer,integer) from public,anon,authenticated;
grant execute on function public.claim_due_typed_reminder_design(timestamptz,integer,integer,integer) to service_role;
revoke execute on function private.remember_email_channels(uuid,jsonb,jsonb,timestamptz),
 private.email_channel_record_history(),
 private.email_discovery_recommendations(uuid,timestamptz,uuid),private.email_discovery_payload_current(uuid,timestamptz),
 private.freeze_email_design_payload() from public,anon,authenticated,service_role;
update private.reminder_projection_sources set dirty=true;
